// Аффиксы (без учёта гармонии гласных — проверку делает словарь)
const SUFFIXES = [
  // глагол: настоящее время (-а/-е/-й + лицо), отрицание, прошедшее на -ды
  'ама', 'еме', 'йма', 'йме', 'аса', 'есе', 'йса', 'йсе', 'ады', 'еди', 'йды', 'йди', 'йду',
  'абыз', 'ебиз', 'йбыз', 'йбиз', 'асыз', 'есиз', 'йсыз', 'йсиз', 'адыла', 'едиле', 'йдыла', 'йдиле',
  'майма', 'мейме', 'майса', 'мейсе', 'майды', 'мейди', 'майбыз', 'мейбиз',
  'дым', 'дим', 'дум', 'дюм', 'дынг', 'динг', 'дунг', 'дюнг', 'ды', 'ди', 'ду', 'дю',
  'дыкъ', 'дик', 'дукъ', 'дюк', 'дыгъыз', 'дигиз', 'дула', 'дюле', 'дыла', 'диле',
  // сказуемость: -ма/-са/-ды/-быз/-сыз/-дыла
  'ма', 'ме', 'са', 'се', 'быз', 'биз', 'сыз', 'сиз',
  // множественное число
  'ла', 'ле', 'лары', 'лери', 'ларыбыз',
  // принадлежность
  'ым', 'им', 'ум', 'юм', 'м', 'ынг', 'инг', 'унг', 'юнг', 'нг', 'сы', 'си', 'су', 'сю', 'ы', 'и', 'у', 'ю',
  'ыбыз', 'ибиз', 'убуз', 'юбюз', 'быз', 'ыгъыз', 'игиз', 'угъуз', 'югюз',
  // падежи
  'ны', 'ни', 'ну', 'ню', 'гъа', 'ге', 'къа', 'ке', 'а', 'е', 'да', 'де', 'та', 'те', 'дан', 'ден', 'тан', 'тен', 'ндан', 'нден', 'нда', 'нде'
];
const UNIQUE_SUFFIXES = [...new Set(SUFFIXES)];
const INF = ['ргъа', 'рге', 'аргъа', 'ерге', 'ыргъа', 'ирге', 'ургъа', 'юрге'];

function resolve(stem) {
  if (DICT.has(stem)) return stem;
  for (const e of INF) if (DICT.has(stem + e)) return stem + e;
  // сюй-: сюеме → сюерге
  if (stem.endsWith('й')) for (const e of INF) if (DICT.has(stem.slice(0, -1) + e.replace(/^[аеыиую]/, 'е'))) return stem.slice(0, -1) + e.replace(/^[аеыиую]/, 'е');
  return '';
}

export function lemma(raw) {
  const w = lower(raw).replace(/[’`]/g, "'").replace(/^[^\p{L}-]+|[^\p{L}-]+$/gu, '');
  if (!w) return '';
  if (FORMS[w]) return FORMS[w];
  if (DICT.has(w)) return w;
  let level = [w];
  const seen = new Set(level);
  for (let depth = 0; depth < 5 && level.length; depth++) {
    const next = [];
    let best = '', bestLen = 0;
    for (const s of level) {
      for (const suf of UNIQUE_SUFFIXES) {
        if (!s.endsWith(suf) || s.length - suf.length < 2) continue;
        const stem = s.slice(0, -suf.length);
        const hit = FORMS[stem] || resolve(stem);
        if (hit && stem.length > bestLen) { best = hit; bestLen = stem.length; }
        if (!seen.has(stem)) { seen.add(stem); next.push(stem); }
      }
    }
    if (best) return best;
    level = next;
  }
  return w;
}

export function lookup(raw) {
  const l = lemma(raw);
  return { word: l, translation: DICT.get(l) || '' };
}
